					<span class="orderTime">{{item.timeAgo}}</span>
					<span v-if="item.distanceToPickupText" class="distance">距取件 {{item.distanceToPickupText}}</span>
					<span v-if="item.recommendReason" class="recommend-reason">{{item.recommendReason}}</span>
