				{{recommendedOrder.recommendReason}}
			</div>
			<div class="recommend-actions">
				<nut-button class="recommend-secondary" @click="viewRecommendedOrder">查看详情</nut-button>
				<nut-button class="recommend-primary" :loading="acceptingRecommend" @click="acceptRecommendedOrder">立即接单</nut-button>
			</div>
			<div class="recommend-close" @click="closeRecommendPopup">稍后处理</div>
		</div>
	</nut-popup>
</template>

<script>
	import dayjs from 'dayjs';
	import relativeTime from 'dayjs/plugin/relativeTime'; // 引入 relativeTime 插件
	import 'dayjs/locale/zh-cn';  // 导入中文语言包
	// 扩展 dayjs 插件
	dayjs.extend(relativeTime);
	// 设置为中文
	dayjs.locale('zh-cn');
	import {
		getNearbyOrderHall,
		getAccept
	} from "@/request/apis/order.js"
	import {
		reportRiderLocation
	} from "@/request/apis/runner.js"
	import ws from '@/request/websocket.js'
	export default {
		data() {
			return {
				skeletonLoading:true,
				locationTimer:null,
				currSchool: null,
				tabValue: 0,
				title: 'Hello',
				queryParams: {
					schoolId: null,
					status: null,
					pageSize: 20,
					pageNum: 1
				},
				rows: [],
				total: 0,
				hasMore: true,
				showRecommendPopup: false,
				recommendedOrder: null,
				acceptingRecommend: false,
				shownRecommendOrderIds: []
			}
		},
		onLoad() {
			this.skeletonLoading = true
			this.initData()
		},
		onShow() {
			this.initData()
			ws.init()
			uni.$off('ws-message', this.handleWsMessage)
			uni.$on('ws-message', this.handleWsMessage)
			this.startLocationTimer()
			this.refreshList()
		},
		onHide() {
			uni.$off('ws-message', this.handleWsMessage)
			this.clearLocationTimer()
		},
		onUnload() {
			uni.$off('ws-message', this.handleWsMessage)
			this.clearLocationTimer()
		},
		onReachBottom() {
			if (this.hasMore) {
				this.getList(); // 触底时加载更多
			}
		},
		onPullDownRefresh() {
			this.skeletonLoading = true
			this.refreshList()
		},
		methods: {
			toOrderDetailRunner(e) {
				console.log(e);
				uni.navigateTo({
					url:"/pages/API/order/runner/runner?orderId=" + e.id
				})
			},
			handleWsMessage(message) {
				if(!message || message.type !== 'NEW_RECOMMENDED_ORDER') {
					return
				}
				this.recommendedOrder = this.buildRecommendedOrder(message)
				this.showRecommendPopup = true
				uni.showToast({
					title: message.title || '附近有新订单',
					icon: 'none',
					duration: 2000
				})
				this.refreshList()
			},
			buildRecommendedOrder(message) {
				return {
					orderId: message.orderId,
					title: message.title || '附近新订单',
					pickupTitle: message.pickupTitle,
					deliveryTitle: message.deliveryTitle,
					distanceToPickupText: message.distanceToPickupText,
					payableAmount: message.payableAmount,
					dispatchScore: message.dispatchScore,
					recommendReason: message.recommendReason
				}
			},
			buildRecommendedOrderFromRow(order) {
				const startAddress = order.startAddress || {}
				const endAddress = order.endAddress || {}
				return {
					orderId: order.id,
					title: '系统推荐订单',
					pickupTitle: startAddress.title || startAddress.name || '取件地址',
					deliveryTitle: endAddress.title || endAddress.name || '送达地址',
					distanceToPickupText: order.distanceToPickupText,
					payableAmount: order.totalAmount,
					dispatchScore: order.dispatchScore,
					recommendReason: order.recommendReason
				}
			},
			showFirstRecommendedOrder(orders) {
				if(this.showRecommendPopup || !orders || orders.length === 0) {
					return
				}
				const target = orders.find(item => item.recommended && this.shownRecommendOrderIds.indexOf(item.id) === -1)
				if(!target) {
					return
				}
				this.shownRecommendOrderIds.push(target.id)
				this.recommendedOrder = this.buildRecommendedOrderFromRow(target)
				this.showRecommendPopup = true
			},
			closeRecommendPopup() {
				this.showRecommendPopup = false
			},
			viewRecommendedOrder() {
				if(!this.recommendedOrder || !this.recommendedOrder.orderId) {
					return
				}
				this.showRecommendPopup = false
				uni.navigateTo({
					url:"/pages/API/order/runner/runner?orderId=" + this.recommendedOrder.orderId
				})
			},
			acceptRecommendedOrder() {
				if(!this.recommendedOrder || !this.recommendedOrder.orderId || this.acceptingRecommend) {
					return
				}
				this.acceptingRecommend = true
				getAccept(this.recommendedOrder.orderId).then(() => {
					const orderId = this.recommendedOrder.orderId
					uni.showToast({
						title: '接单成功',
						icon: 'success'
					})
					this.showRecommendPopup = false
					this.refreshList()
					uni.navigateTo({
						url:"/pages/API/order/runner/runner?orderId=" + orderId
					})
				}).catch(err => {
					uni.showToast({
						title: err || '接单失败',
						icon:"none",
						duration:3000
					})
					this.refreshList()
				}).finally(() => {
					this.acceptingRecommend = false
				})
			},
			tabChange(e) {
				let key = e.paneKey
				if(key == '0') this.queryParams.status = null
				if(key == '1') this.queryParams.status = 1
				this.resizePage()
				this.skeletonLoading = true
				this.refreshList()
			},
			initData() {
				this.currSchool = this.$store.state.currSchool || uni.getStorageSync("currentSchool") || {};
				const userInfo = this.$store.state.userInfo || {}
				const userWx = userInfo.userWx || {}
				this.queryParams.schoolId = this.currSchool.id || userWx.schoolId || null
			},
			resizePage() {
				this.queryParams.pageNum = 1;
				this.queryParams.pageSize = 20;
				this.rows = [];
				this.total = 0;
				this.hasMore = true
			},
			refreshList() {
				this.resizePage()
				this.reportCurrentLocation().finally(() => {
					this.getList()
				})
			},
			startLocationTimer() {
				this.clearLocationTimer()
				this.reportCurrentLocation()
				this.locationTimer = setInterval(() => {
					this.reportCurrentLocation()
				}, 30000)
			},
			clearLocationTimer() {
				if(this.locationTimer) {
					clearInterval(this.locationTimer)
					this.locationTimer = null
				}
			},
			reportCurrentLocation() {
				return new Promise((resolve, reject) => {
					uni.getLocation({
						type:'gcj02',
						success(res) {
							reportRiderLocation({
								lng:res.longitude,
								lat:res.latitude,
								locationSource:'miniapp'
							}).then(resolve).catch(reject)
						},
						fail(err) {
							reject(err)
						}
					})
				})
			},
			getList() {
				const nearbyParams = {
					status: this.queryParams.status,
					pageSize: this.queryParams.pageSize,
					pageNum: this.queryParams.pageNum
				}
				getNearbyOrderHall(nearbyParams).then(res => {
					console.log(res);
					let data = res.rows
					for (var i = 0; i < data.length; i++) {
						data[i].timeAgo = dayjs(data[i].createTime).fromNow()
					}
					res.rows = data
					this.total = res.total
					this.rows.push(...res.rows)
					this.showFirstRecommendedOrder(res.rows)
					this.queryParams.pageNum += 1;
					this.hasMore = res.rows.length > 0
					
					this.skeletonLoading = false
					uni.stopPullDownRefresh();
				}).catch(err => {
					uni.showToast({
						title: err || '\u9644\u8fd1\u8ba2\u5355\u67e5\u8be2\u5931\u8d25',
						icon:"none",
						duration:3000
					})
				})
			},
		}
	}
</script>

